#!/usr/bin/env python3
"""
patch-152-c — Customer notifications for deliveries.

What ships:
  - TenantDeliveryNotificationService — sends email + SMS when a
    delivery is scheduled. Respects per-tenant notification toggles
    (defaults ON unless explicitly disabled). Records notified_at +
    notification_channels on the delivery row.
  - Two default email templates in EmailService: delivery_pickup_scheduled
    and delivery_dropoff_scheduled (overridable per tenant via
    tenant_email_templates table — same as booking confirmation).
  - SMS body inline (no template table for SMS in current codebase).
  - DeliveriesController::store now fires the notification after
    successful save. Failures are logged but never block the save.
  - update() does NOT re-fire — editing notes shouldn't spam customers.
  - Settings panel: "Delivery scheduled" Email + SMS toggles next to
    "Booking confirmation" in the Notifications card. Wired through
    SettingsController::updateCommunication validate + save.
  - Drawer banner: dynamic copy showing which channels will fire
    based on current settings, with link to settings if both off.

Standalone Python. No external files. Bash-version-independent.
Idempotent. Re-running is safe.

Usage:
  python3 patch-152-c.py . --apply
"""
import argparse, base64, pathlib, sys

